use glam::DVec3;use ingetrazo_core::parts::{part_size,part_summary,cut_list};use ingetrazo_gui::IngeTrazoApp;
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let input:serde_json::Value=serde_json::from_slice(&std::fs::read(dir.join("points.json")).unwrap()).unwrap();let sizes=input.as_array().unwrap().iter().map(|case|{let points=case.as_array().unwrap().iter().map(|p|DVec3::from_array(serde_json::from_value::<[f64;3]>(p.clone()).unwrap())).collect::<Vec<_>>();part_size(&points)}).collect::<Vec<_>>();let mut app=IngeTrazoApp::new();app.scene=ingetrazo_formats::igz::load_igz(&dir.join("source.igz")).unwrap();let rows=app.scene.groups.iter().map(part_summary).collect::<Vec<_>>();let summaries=rows.iter().map(|r|serde_json::json!({"name":r.name,"material":r.material,"size":r.size,"faces":r.faces,"hidden":r.hidden})).collect::<Vec<_>>();let mut lists=vec![];for precision in [1.,2.,0.5]{for by_material in [false,true]{for surfaces in [false,true]{let rows=rows.iter().filter(|r|surfaces||!ingetrazo_core::parts::is_surface(r.size)).cloned().collect::<Vec<_>>();let lines=cut_list(&rows,precision,by_material);lists.push(serde_json::json!({"precision":precision,"by_material":by_material,"surfaces":surfaces,"lines":lines.iter().map(|r|serde_json::json!({"names":r.names,"materials":r.materials,"size":r.size,"qty":r.quantity})).collect::<Vec<_>>()}));}}}
let mut texts=serde_json::Map::new();for(unit,name)in[(ingetrazo_core::units::LengthUnit::Meters,"m"),(ingetrazo_core::units::LengthUnit::Centimeters,"cm"),(ingetrazo_core::units::LengthUnit::Millimeters,"mm"),(ingetrazo_core::units::LengthUnit::Inches,"in"),(ingetrazo_core::units::LengthUnit::Feet,"ft")]{app.scene.unit=unit;texts.insert(name.into(),app.outliner_cut_list().into());}std::fs::write(dir.join("result.json"),serde_json::to_vec(&serde_json::json!({"sizes":sizes,"summaries":summaries,"lists":lists,"texts":texts})).unwrap()).unwrap();}
